/**
 * Anatomy registry: stable structure ids, hierarchy, ontology links and voice
 * aliases. Pure data (no Three.js). It is generated by tools/anatomy-pipeline
 * from structures.yaml; ids never come from mesh file names.
 */
export type Vec3 = [number, number, number];

export interface StructureDef {
  id: string;
  name: string;
  kind: 'group' | 'structure';
  /** GLB node name for mesh-bearing structures (dot-free; see the pipeline). */
  node?: string;
  system: string;
  parent: string | null;
  /** Foundational Model of Anatomy concept id, when one exists. */
  fma: string | null;
  aliases: string[];
  children: string[];
  /** True when the geometry is a generated approximation, not source anatomy. */
  approximate?: boolean;
  tris?: number;
  /** Model-space centre and size in metres (model origin is mid-thorax). */
  center?: Vec3;
  size?: Vec3;
}

export interface RegistryDoc {
  schema: number;
  model: { glb: string; nodeNameField: string };
  source: { name: string; release: string; attribution: string; url: string };
  systems: Record<string, { name: string }>;
  totalTriangles: number;
  structures: StructureDef[];
}

export class AnatomyRegistry {
  readonly doc: RegistryDoc;
  private byId = new Map<string, StructureDef>();
  private byNode = new Map<string, string>();
  private leafCache = new Map<string, string[]>();

  constructor(doc: RegistryDoc) {
    if (doc.schema !== 1) throw new Error(`Unsupported anatomy registry schema ${doc.schema}`);
    this.doc = doc;
    for (const s of doc.structures) {
      this.byId.set(s.id, s);
      if (s.node) this.byNode.set(s.node, s.id);
    }
  }

  has(id: string): boolean {
    return this.byId.has(id);
  }

  /**
   * Whether a structure (or a group, via its members) may be cited as evidence in clinical
   * reasoning. Generated approximate geometry (the lung lobe envelopes) never may. Future
   * clinical modules must call this instead of re-deriving the rule.
   */
  isEvidenceEligible(id: string): boolean {
    const leaves = this.leaves(id);
    return leaves.length > 0 && leaves.every((leaf) => !this.byId.get(leaf)?.approximate);
  }

  /** Structure id for a GLB node name, or undefined for nodes that are not structures. */
  idForNode(nodeName: string): string | undefined {
    return this.byNode.get(nodeName);
  }

  get(id: string): StructureDef | undefined {
    return this.byId.get(id);
  }

  all(): StructureDef[] {
    return this.doc.structures;
  }

  /** Ids of mesh-bearing structures under `id` (itself, if it is one). */
  leaves(id: string): string[] {
    const cached = this.leafCache.get(id);
    if (cached) return cached;
    const def = this.byId.get(id);
    const out: string[] = [];
    if (def) {
      if (def.kind === 'structure') out.push(id);
      for (const child of def.children) out.push(...this.leaves(child));
    }
    this.leafCache.set(id, out);
    return out;
  }

  /** True when `id` is `ancestorId` or lies anywhere below it. */
  isWithin(id: string, ancestorId: string): boolean {
    let cursor: string | null = id;
    while (cursor) {
      if (cursor === ancestorId) return true;
      cursor = this.byId.get(cursor)?.parent ?? null;
    }
    return false;
  }

  /** Parent chain, nearest first. */
  ancestors(id: string): StructureDef[] {
    const out: StructureDef[] = [];
    let cursor = this.byId.get(id)?.parent ?? null;
    while (cursor) {
      const def = this.byId.get(cursor);
      if (!def) break;
      out.push(def);
      cursor = def.parent;
    }
    return out;
  }

  /** Systems that actually contain geometry in the loaded model. */
  systemsWithGeometry(): string[] {
    const set = new Set<string>();
    for (const s of this.doc.structures) if (s.kind === 'structure') set.add(s.system);
    return [...set];
  }

  /** Resolve a spoken or typed name ("right upper lobe") to a structure id. */
  findByAlias(text: string): string | null {
    const needle = text.trim().toLowerCase();
    for (const s of this.doc.structures) {
      if (s.name.toLowerCase() === needle || s.aliases.some((a) => a.toLowerCase() === needle)) {
        return s.id;
      }
    }
    return null;
  }
}

export async function loadRegistry(url: string): Promise<AnatomyRegistry> {
  const response = await fetch(url);
  if (!response.ok) throw new Error(`Anatomy registry ${url}: HTTP ${response.status}`);
  return new AnatomyRegistry((await response.json()) as RegistryDoc);
}
